(function () {
  "use strict";
  function initSteppers() {
    document.addEventListener("click", function (ev) {
      var btn = ev.target.closest("[data-step-target]");
      if (!btn) return;
      var input = document.getElementById(btn.getAttribute("data-step-target"));
      if (!input) return;
      var delta = parseInt(btn.getAttribute("data-step-delta") || "0", 10);
      var cur = parseInt(input.value || "0", 10) || 0;
      var min = input.min !== "" ? parseInt(input.min, 10) : 0;
      var max = input.max !== "" ? parseInt(input.max, 10) : 99;
      var next = Math.max(min, Math.min(max, cur + delta));
      input.value = String(next);
      input.dispatchEvent(new Event("input", { bubbles: true }));
      input.dispatchEvent(new Event("change", { bubbles: true }));
    });
  }

  document.addEventListener("DOMContentLoaded", initSteppers);
})();

